{
  "name": "jj-opencode",
  "version": "0.2.0",
  "description": "OpenCode plugin for JJ VCS - enforces 'define change before implementation' workflow",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "type": "module",
  "bin": {
    "jj-opencode-setup": "./bin/setup.js"
  },
  "scripts": {
    "build": "tsc",
    "clean": "rm -rf dist",
    "prepublishOnly": "npm run build"
  },
  "files": [
    "dist",
    "bin",
    "commands"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "jj",
    "jujutsu",
    "vcs",
    "version-control"
  ],
  "author": "DPS",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/dpshade/jj-opencode"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=0.1.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "typescript": "^5.0.0"
  }
}
